/**
 * Pick up any hand-authored migrations dropped into migrations/_manual/.
 * Files are picked up in lexicographic order; `marrowc diff --write` writes
 * them with a numeric prefix so insertion order is stable.
 */
function loadManualBlocks(): Block[] {
  const dir = path.resolve(__dirname, "..", "migrations", "_manual");
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter(f => f.endsWith(".sql"))
    .sort()
    .map(f => {
      const sql = fs.readFileSync(path.join(dir, f), "utf-8");
      return {
        id: "manual_" + f.replace(/\.sql$/, ""),
        checksum: createHash("sha256").update(sql).digest("hex"),
        sql,
      };
    });
}

const LEDGER_DDL = `CREATE TABLE IF NOT EXISTS schema_migrations (
  id           VARCHAR PRIMARY KEY,
  checksum     VARCHAR NOT NULL,
  applied_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  applied_by   VARCHAR NOT NULL DEFAULT current_user,
  duration_ms  INTEGER NOT NULL DEFAULT 0
);`;

async function migrate() {
  const client = await pool.connect();
  let applied = 0, skipped = 0;
  try {
    await client.query(LEDGER_DDL);

    // Generated blocks come first (compile-time schema), then manual diffs.
    const allBlocks: Block[] = [...GENERATED_BLOCKS, ...loadManualBlocks()];

    // Load already-applied entries.
    const existing = await client.query(
      "SELECT id, checksum FROM schema_migrations"
    );
    const rows = existing.rows as Array<{ id: string; checksum: string }>;
    const appliedById = new Map(rows.map(r => [r.id, r.checksum]));

    for (const block of allBlocks) {
      const prior = appliedById.get(block.id);
      if (prior === block.checksum) {
        skipped++;
        continue;
      }
      if (prior && prior !== block.checksum) {
        // Someone changed an already-applied migration. Refuse to proceed —
        // an explicit migration file should be authored instead.
        throw new Error(
          `Migration ${block.id} was previously applied with a different ` +
          `checksum. Generate a new migration via 'marrowc diff --write' ` +
          `instead of editing existing schemas.`
        );
      }

      const start = Date.now();
      try {
        await client.query("BEGIN");
        await client.query(block.sql);
        await client.query(
          "INSERT INTO schema_migrations (id, checksum, duration_ms) VALUES ($1, $2, $3)",
          [block.id, block.checksum, Date.now() - start]
        );
        await client.query("COMMIT");
        console.log(`  applied  ${block.id}  (${Date.now() - start}ms)`);
        applied++;
      } catch (e) {
        await client.query("ROLLBACK").catch(() => {});
        throw e;
      }
    }

    console.log(`Migrations complete: ${applied} applied, ${skipped} already up to date.`);
  } finally {
    client.release();
    await pool.end();
  }
}

migrate().catch(e => { console.error(e); process.exit(1); });